import 'package:flutter/material.dart';
import 'package:intl/intl.dart';

void main() => runApp(const MyApp());

class MyApp extends StatefulWidget {
  const MyApp({super.key});

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  DateTime? _selectedDate;
  TimeOfDay? _selectedTime;
  DateTimeRange? _selectedDateRange;
  DateTime? _birthDate;

  final DateFormat _dateFormat = DateFormat('dd.MM.yyyy');

  Future<void> _selectDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _selectedDate ?? DateTime.now(),
      firstDate: DateTime(2020),
      lastDate: DateTime(2030),
      helpText: 'Күнді таңдаңыз',
      cancelText: 'Бас тарту',
      confirmText: 'Таңдау',
    );

    if (picked != null) {
      setState(() => _selectedDate = picked);
    }
  }

  Future<void> _selectTime() async {
    final picked = await showTimePicker(
      context: context,
      initialTime: _selectedTime ?? TimeOfDay.now(),
      helpText: 'Уақытты таңдаңыз',
      cancelText: 'Бас тарту',
      confirmText: 'Таңдау',
    );

    if (picked != null) {
      setState(() => _selectedTime = picked);
    }
  }

  Future<void> _selectDateRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime.now(),
      lastDate: DateTime.now().add(const Duration(days: 365)),
      initialDateRange: _selectedDateRange,
      helpText: 'Кезеңді таңдаңыз',
      cancelText: 'Бас тарту',
      confirmText: 'Таңдау',
      saveText: 'Сақтау',
    );

    if (picked != null) {
      setState(() => _selectedDateRange = picked);
    }
  }

  Future<void> _selectBirthDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _birthDate ?? DateTime(2000),
      firstDate: DateTime(1900),
      lastDate: DateTime.now(),
      initialDatePickerMode: DatePickerMode.year,
      helpText: 'Туған күні',
    );

    if (picked != null) {
      setState(() => _birthDate = picked);
    }
  }

  String _formatTime(TimeOfDay? time) {
    if (time == null) return 'Таңдалмаған';
    final hour = time.hour.toString().padLeft(2, '0');
    final minute = time.minute.toString().padLeft(2, '0');
    return '$hour:$minute';
  }

  int _calculateAge(DateTime birthDate) {
    final now = DateTime.now();
    int age = now.year - birthDate.year;
    if (now.month < birthDate.month ||
        (now.month == birthDate.month && now.day < birthDate.day)) {
      age--;
    }
    return age;
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('DatePicker & TimePicker'),
        ),
        body: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text(
                '1. Күнді таңдау:',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _selectDate,
                icon: const Icon(Icons.calendar_today),
                label: Text(
                  _selectedDate != null
                      ? _dateFormat.format(_selectedDate!)
                      : 'Күнді таңдаңыз',
                ),
              ),

              const SizedBox(height: 24),

              const Text(
                '2. Уақытты таңдау:',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _selectTime,
                icon: const Icon(Icons.access_time),
                label: Text(
                  _selectedTime != null
                      ? _formatTime(_selectedTime)
                      : 'Уақытты таңдаңыз',
                ),
              ),

              const SizedBox(height: 24),

              const Text(
                '3. Күндер аралығы (бронь):',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _selectDateRange,
                icon: const Icon(Icons.date_range),
                label: Text(
                  _selectedDateRange != null
                      ? '${_dateFormat.format(_selectedDateRange!.start)} - ${_dateFormat.format(_selectedDateRange!.end)}'
                      : 'Кезеңді таңдаңыз',
                ),
              ),
              if (_selectedDateRange != null) ...[
                const SizedBox(height: 8),
                Text(
                  'Күндер саны: ${_selectedDateRange!.end.difference(_selectedDateRange!.start).inDays + 1}',
                  style: TextStyle(color: Colors.grey.shade600),
                ),
              ],

              const SizedBox(height: 24),

              const Text(
                '4. Туған күні:',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _selectBirthDate,
                icon: const Icon(Icons.cake),
                label: Text(
                  _birthDate != null
                      ? '${_dateFormat.format(_birthDate!)} (${_calculateAge(_birthDate!)} жас)'
                      : 'Туған күнін көрсетіңіз',
                ),
              ),

              const SizedBox(height: 32),

              Card(
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Row(
                        children: [
                          Icon(Icons.flight, color: Colors.blue),
                          SizedBox(width: 8),
                          Text(
                            'Әуе билетін брондау',
                            style: TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),

                      ListTile(
                        leading: const Icon(Icons.flight_takeoff),
                        title: const Text('Ұшу күні'),
                        subtitle: Text(
                          _selectedDate != null
                              ? _dateFormat.format(_selectedDate!)
                              : 'Таңдалмаған',
                        ),
                        trailing: const Icon(Icons.chevron_right),
                        onTap: _selectDate,
                      ),

                      ListTile(
                        leading: const Icon(Icons.schedule),
                        title: const Text('Ұшу уақыты'),
                        subtitle: Text(_formatTime(_selectedTime)),
                        trailing: const Icon(Icons.chevron_right),
                        onTap: _selectTime,
                      ),

                      const SizedBox(height: 16),

                      SizedBox(
                        width: double.infinity,
                        child: ElevatedButton(
                          onPressed: _selectedDate != null && _selectedTime != null
                              ? () {
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    SnackBar(
                                      content: Text(
                                        '${_dateFormat.format(_selectedDate!)} ${_formatTime(_selectedTime)} рейстерін іздеу',
                                      ),
                                    ),
                                  );
                                }
                              : null,
                          child: const Text('Рейстерді табу'),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

